CREATE TABLE receivable (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, receivable_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, agreement_id BIGINT NOT NULL, bill_id BIGINT NOT NULL, charge_type VARCHAR(32) NOT NULL, due_date DATE NOT NULL, original_amount DECIMAL(18,2) NOT NULL, adjustment_amount DECIMAL(18,2) NOT NULL DEFAULT 0, receivable_amount DECIMAL(18,2) NOT NULL, allocated_amount DECIMAL(18,2) NOT NULL DEFAULT 0, outstanding_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_recv(tenant_id,receivable_no), UNIQUE KEY uk_recv_bill_charge(tenant_id,bill_id,charge_type), KEY idx_recv_customer(tenant_id,customer_id,status,due_date), KEY idx_recv_ag(tenant_id,agreement_id));
CREATE TABLE receivable_adjustment (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, receivable_id BIGINT NOT NULL, adjustment_type VARCHAR(32) NOT NULL, amount DECIMAL(18,2) NOT NULL, reason VARCHAR(512) NOT NULL, workflow_instance_id VARCHAR(128) NULL, status VARCHAR(32) NOT NULL, created_by BIGINT NOT NULL, created_at DATETIME(3) NOT NULL, KEY idx_recv_adj(tenant_id,receivable_id,status));
CREATE TABLE collection_record (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, collection_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, collection_type VARCHAR(32) NOT NULL, source_type VARCHAR(32) NOT NULL, source_id BIGINT NOT NULL, currency CHAR(3) NOT NULL, amount DECIMAL(18,2) NOT NULL, allocated_amount DECIMAL(18,2) NOT NULL DEFAULT 0, unallocated_amount DECIMAL(18,2) NOT NULL, collection_date DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_collection_no(tenant_id,collection_no), UNIQUE KEY uk_collection_source(tenant_id,source_type,source_id), KEY idx_collection_customer(tenant_id,customer_id,status));
CREATE TABLE payment_allocation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, collection_id BIGINT NOT NULL, receivable_id BIGINT NOT NULL, allocation_amount DECIMAL(18,2) NOT NULL, allocation_type VARCHAR(32) NOT NULL, operator_id BIGINT NULL, allocated_at DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, KEY idx_alloc_collection(tenant_id,collection_id), KEY idx_alloc_recv(tenant_id,receivable_id));
CREATE TABLE allocation_reversal (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, original_allocation_id BIGINT NOT NULL, reversal_amount DECIMAL(18,2) NOT NULL, reason VARCHAR(512) NOT NULL, operator_id BIGINT NOT NULL, reversed_at DATETIME(3) NOT NULL, UNIQUE KEY uk_alloc_rev_once(tenant_id,original_allocation_id,id));
CREATE TABLE customer_advance (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, collection_id BIGINT NOT NULL, currency CHAR(3) NOT NULL, original_amount DECIMAL(18,2) NOT NULL, available_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, KEY idx_adv_customer(tenant_id,customer_id,status));
CREATE TABLE invoice_quota_reservation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, allocation_id BIGINT NOT NULL, invoice_application_id BIGINT NOT NULL, reserved_amount DECIMAL(18,2) NOT NULL, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_quota_app(tenant_id,invoice_application_id), KEY idx_quota_alloc(tenant_id,allocation_id,status));
CREATE TABLE account (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, account_code VARCHAR(64) NOT NULL, account_name VARCHAR(128) NOT NULL, account_type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_account(tenant_id,account_code));
CREATE TABLE accounting_entry (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, entry_no VARCHAR(64) NOT NULL, business_type VARCHAR(32) NOT NULL, business_id BIGINT NOT NULL, posting_type VARCHAR(32) NOT NULL, occurred_at DATETIME(3) NOT NULL, posting_date DATE NOT NULL, status VARCHAR(32) NOT NULL, description VARCHAR(512) NULL, UNIQUE KEY uk_entry_no(tenant_id,entry_no), UNIQUE KEY uk_entry_biz(tenant_id,business_type,business_id,posting_type));
CREATE TABLE accounting_line (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, entry_id BIGINT NOT NULL, account_code VARCHAR(64) NOT NULL, direction VARCHAR(8) NOT NULL, amount DECIMAL(18,2) NOT NULL, currency CHAR(3) NOT NULL, customer_id BIGINT NULL, agreement_id BIGINT NULL, KEY idx_line_entry(tenant_id,entry_id));
CREATE TABLE dunning_case (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, receivable_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, dunning_level INT NOT NULL DEFAULT 1, promised_amount DECIMAL(18,2) NULL, promised_date DATE NULL, owner_user_id BIGINT NULL, next_action_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_dunning_recv(tenant_id,receivable_id), KEY idx_dunning_owner(tenant_id,owner_user_id,status,next_action_at));
CREATE TABLE reconciliation_batch (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, batch_no VARCHAR(64) NOT NULL, channel VARCHAR(32) NOT NULL, statement_date DATE NOT NULL, status VARCHAR(32) NOT NULL, total_channel_count BIGINT NOT NULL DEFAULT 0, total_local_count BIGINT NOT NULL DEFAULT 0, matched_count BIGINT NOT NULL DEFAULT 0, exception_count BIGINT NOT NULL DEFAULT 0, started_at DATETIME(3) NULL, finished_at DATETIME(3) NULL, UNIQUE KEY uk_recon_batch(tenant_id,batch_no), UNIQUE KEY uk_recon_day(tenant_id,channel,statement_date));
CREATE TABLE reconciliation_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, batch_id BIGINT NOT NULL, channel_trade_no VARCHAR(128) NULL, payment_no VARCHAR(64) NULL, channel_amount DECIMAL(18,2) NULL, local_amount DECIMAL(18,2) NULL, channel_status VARCHAR(32) NULL, local_status VARCHAR(32) NULL, result_type VARCHAR(64) NOT NULL, exception_id BIGINT NULL, KEY idx_recon_item_batch(tenant_id,batch_id,result_type));
CREATE TABLE reconciliation_exception (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, exception_no VARCHAR(64) NOT NULL, exception_type VARCHAR(64) NOT NULL, severity VARCHAR(16) NOT NULL, business_type VARCHAR(32) NULL, business_id BIGINT NULL, channel_payload JSON NULL, local_payload JSON NULL, status VARCHAR(32) NOT NULL, owner_user_id BIGINT NULL, resolution_type VARCHAR(64) NULL, resolution_reason VARCHAR(1024) NULL, resolved_by BIGINT NULL, resolved_at DATETIME(3) NULL, UNIQUE KEY uk_recon_ex(tenant_id,exception_no), KEY idx_recon_ex_status(tenant_id,status,severity));
CREATE TABLE channel_statement (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, channel VARCHAR(32) NOT NULL, statement_date DATE NOT NULL, file_id BIGINT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_stmt(tenant_id,channel,statement_date));
CREATE TABLE channel_statement_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, statement_id BIGINT NOT NULL, channel_trade_no VARCHAR(128) NOT NULL, merchant_order_no VARCHAR(128) NULL, trade_type VARCHAR(32) NOT NULL, amount DECIMAL(18,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, occurred_at DATETIME(3) NOT NULL, KEY idx_stmt_trade(tenant_id,channel_trade_no));
